/**
* Mengompresi file gambar dari laptop/HP menggunakan HTML5 Canvas
* Menghasilkan DataURL yang tajam namun ringan (~30-60KB) sehingga localStorage tidak penuh
*/
function kompresGambar(file, maxDimensi, kualitas, callback) {
	if (!file) return;
	// Jika file adalah SVG, baca langsung sebagai Data URL
	if (file.type === "image/svg+xml") {
		const readerSvg = new FileReader();
		readerSvg.onload = function(e) {
			if (typeof callback === "function") callback(e.target.result);
		};
		readerSvg.readAsDataURL(file);
		return;
	}
	const reader = new FileReader();
	reader.onload = function(event) {
		const img = new Image();
		img.onload = function() {
			const canvas = document.createElement("canvas");
			let width = img.width;
			let height = img.height;
			const batasMaks = maxDimensi || 700;
			if (width > height) {
				if (width > batasMaks) {
					height = Math.round(height * batasMaks / width);
					width = batasMaks;
				}
			} else {
				if (height > batasMaks) {
					width = Math.round(width * batasMaks / height);
					height = batasMaks;
				}
			}
			canvas.width = width;
			canvas.height = height;
			const ctx = canvas.getContext("2d");
			ctx.drawImage(img, 0, 0, width, height);
			// Konversi ke format JPEG dengan kompresi optimal
			const hasilDataUrl = canvas.toDataURL("image/jpeg", kualitas || .82);
			if (typeof callback === "function") {
				callback(hasilDataUrl);
			}
		};
		img.src = event.target.result;
	};
	reader.readAsDataURL(file);
}
// ------------------------------------------------------------------------------
// 3. FUNGSI PENYIMPANAN LOCALSTORAGE
// ------------------------------------------------------------------------------
/**
* Mengambil data dari localStorage. Jika belum pernah disimpan,
* maka otomatis mengisi localStorage dengan DATA_AWAL_DEFAULT.
*/
function ambilDataToko() {
	try {
		const dataTersimpan = localStorage.getItem(STORAGE_KEY);
		if (!dataTersimpan) {
			localStorage.setItem(STORAGE_KEY, JSON.stringify(DATA_AWAL_DEFAULT));
			return DATA_AWAL_DEFAULT;
		}
		return JSON.parse(dataTersimpan);
	} catch (error) {
		console.error("Gagal membaca localStorage:", error);
		return DATA_AWAL_DEFAULT;
	}
}
/**
* Menyimpan data yang diperbarui ke localStorage
*/
function simpanDataToko(dataBaru) {
	try {
		localStorage.setItem(STORAGE_KEY, JSON.stringify(dataBaru));
		// Memicu penerapan perubahan warna langsung
		terapkanWarnaTema(dataBaru);
		return true;
	} catch (error) {
		console.error("Gagal menyimpan ke localStorage:", error);
		return false;
	}
}
/**
* Menerapkan variabel CSS tema warna ke elemen :root
*/
function terapkanWarnaTema(data) {
	if (!data) return;
	const root = document.documentElement;
	if (data.warnaUtama) root.style.setProperty("--warna-utama", data.warnaUtama);
	if (data.warnaAksen) root.style.setProperty("--warna-aksen", data.warnaAksen);
	if (data.warnaHarga) root.style.setProperty("--warna-harga", data.warnaHarga);
	if (data.warnaLatar) root.style.setProperty("--warna-latar", data.warnaLatar);
}
/**
* Menghasilkan tautan pemesanan WhatsApp otomatis
* Format: https://wa.me/NOMOR_WA?text=PESAN
*/
function buatTautanWa(nomorWa, pesan) {
	// Bersihkan karakter non-digit dari nomor WA
	const nomorBersih = (nomorWa || NOMOR_WA_DEFAULT).toString().replace(/\D/g, "");
	const pesanTersandi = encodeURIComponent(pesan);
	return `https://wa.me/${nomorBersih}?text=${pesanTersandi}`;
}
