function inisialisasiHalamanPublik() {
	const data = ambilDataToko();
	terapkanWarnaTema(data);
	tampilkanDataKeHalamanPublik(data);
	setupNavigasiMobile();
	setupTombolFloatingWa(data);
	// SINKRONISASI DUA JENDELA REAL-TIME:
	// Mendengarkan perubahan pada localStorage dari Jendela 2 (Panel Admin di tab/window lain)
	window.addEventListener("storage", function(e) {
		if (e.key === STORAGE_KEY) {
			const dataTerbaru = ambilDataToko();
			terapkanWarnaTema(dataTerbaru);
			tampilkanDataKeHalamanPublik(dataTerbaru);
			tampilkanToast("Data diperbarui secara langsung dari Panel Kelola!");
		}
	});
}
