/**
* Mengatur tombol menu hamburger di smartphone
*/
function setupNavigasiMobile() {
	const btnMenu = document.getElementById("btn-toggle-menu");
	const navMobile = document.getElementById("nav-menu-mobile");
	if (!btnMenu || !navMobile) return;
	btnMenu.addEventListener("click", function() {
		navMobile.classList.toggle("terbuka");
		const isTerbuka = navMobile.classList.contains("terbuka");
		btnMenu.setAttribute("aria-expanded", isTerbuka);
		btnMenu.innerHTML = isTerbuka ? "✕ Tutup" : "☰ Menu";
	});
	// Tutup menu otomatis jika salah satu tautan diklik
	const navLinks = navMobile.querySelectorAll("a");
	navLinks.forEach(function(link) {
		link.addEventListener("click", function() {
			navMobile.classList.remove("terbuka");
			btnMenu.innerHTML = "☰ Menu";
		});
	});
}
/**
* Mengatur tombol floating WhatsApp di pojok kanan bawah
*/
function setupTombolFloatingWa(data) {
	const floatWa = document.getElementById("btn-wa-floating");
	if (!floatWa) return;
	const pesanTanya = `Halo ${data.namaUsaha}, saya ingin bertanya tentang menu seblak prasmanan.`;
	floatWa.href = buatTautanWa(data.nomorWaLink, pesanTanya);
}
