	setInputValue("input-pemilik", data.pemilik);
	setInputValue("input-berdiri", data.tahunBerdiri);
	setInputValue("input-karyawan", data.jumlahKaryawan);
	setInputValue("input-cerita", data.ceritaUsaha);
	setInputValue("input-foto-utama", data.fotoUtama);
