// 6. FUNGSI PEMBANTU (HELPERS)
// ------------------------------------------------------------------------------
function setInputValue(id, value) {
	const el = document.getElementById(id);
	if (el) el.value = value || "";
}
function getInputValue(id, defaultValue = "") {
	const el = document.getElementById(id);
	return el ? el.value.trim() : defaultValue;
}
/**
* Menampilkan pesan toast melayang sementara di layar
*/
function tampilkanToast(pesan) {
	let toast = document.getElementById("toast-global-notif");
	if (!toast) {
		toast = document.createElement("div");
		toast.id = "toast-global-notif";
		toast.className = "toast-notif";
		document.body.appendChild(toast);
	}
	toast.innerHTML = `<span>💬</span><span>${pesan}</span>`;
	toast.classList.add("aktif");
	setTimeout(function() {
		toast.classList.remove("aktif");
	}, 3500);
}
