/**
* Mengunduh berkas tunggal (index.html, style.css, dll)
*/
async function unduhBerkas(namaBerkas, tipeMime) {
	try {
		const res = await fetch("./" + namaBerkas);
		const teks = await res.text();
		const blob = new Blob([teks], { type: tipeMime || "text/plain" });
		const url = URL.createObjectURL(blob);
		const a = document.createElement("a");
		a.href = url;
		a.download = namaBerkas;
		document.body.appendChild(a);
		a.click();
		document.body.removeChild(a);
		URL.revokeObjectURL(url);
		tampilkanToast(`Berhasil mengunduh ${namaBerkas}`);
	} catch (e) {
		alert("Gagal mengunduh " + namaBerkas);
	}
}
/**
* Mengekspor data localStorage menjadi file backup JSON
*/
function eksporDataJson() {
	const data = ambilDataToko();
	const jsonStr = JSON.stringify(data, null, 2);
	const blob = new Blob([jsonStr], { type: "application/json" });
	const url = URL.createObjectURL(blob);
	const a = document.createElement("a");
	a.href = url;
	a.download = `cadangan-data-seblak-${new Date().toISOString().slice(0, 10)}.json`;
	document.body.appendChild(a);
	a.click();
	document.body.removeChild(a);
	URL.revokeObjectURL(url);
	tampilkanToast("File cadangan data toko (JSON) berhasil diunduh!");
}
/**
* Memulihkan data toko dari file backup JSON
*/
function imporDataJson(file) {
	if (!file) return;
	const reader = new FileReader();
	reader.onload = function(e) {
		try {
			const data = JSON.parse(e.target.result);
			if (data && data.namaUsaha) {
				simpanDataToko(data);
				tampilkanToast("Data toko berhasil dipulihkan dari cadangan!");
				setTimeout(function() {
					location.reload();
				}, 1e3);
			} else {
				alert("Format berkas cadangan JSON tidak sesuai.");
			}
		} catch (err) {
			alert("Gagal membaca file JSON: " + err.message);
		}
	};
	reader.readAsText(file);
}
